export const strategicManagementTextbookHtml = "\n  <div class=\"tkd-page-scope font-sans antialiased bg-[#F7F5F2] text-[#333333]\">\n\n    <!-- COVER HEADER CHO BẢN IN HOẶC XUẤT PDF A4 -->\n    <div class=\"print-document-header hidden print:block text-center border-b-2 border-[#A83245] pb-4 mb-6\">\n      <div class=\"text-[12pt] font-semibold text-[#A83245] tracking-wider uppercase\">TRƯỜNG CAO ĐẲNG KINH TẾ TP. HỒ CHÍ MINH — KHOA QUẢN TRỊ KINH DOANH</div>\n      <h1 class=\"text-[20pt] font-extrabold text-[#111827] uppercase tracking-tight mt-2 mb-1\">\n        GIÁO TRÌNH QUẢN TRỊ CHIẾN LƯỢC (MH17)\n      </h1>\n      <div class=\"text-[11pt] text-[#4B5563] italic\">\n        Tài liệu học tập chính quy bậc Cao đẳng &amp; Đại học — Chủ biên: ThS. NGUYỄN THỊ TRÚC PHƯƠNG\n      </div>\n      <div class=\"text-[10pt] text-[#6B7280] mt-2 flex justify-between items-center border-t border-[#E5E7EB] pt-1\">\n        <span>Mã học phần: MH17 (3 tín chỉ / 45 tiết)</span>\n        <span class=\"print-timestamp\">Năm học: <span class=\"js-current-year\"></span></span>\n        <span>Cổng học liệu số: NGUYỄN THỊ TRÚC PHƯƠNG</span>\n      </div>\n    </div>\n\n    <!-- HEADER BANNER ONLINE LUXURY RED TONE -->\n    <header class=\"no-print w-full bg-gradient-to-r from-[#A83245] via-[#C65B69] to-[#742D3A] text-white py-8 sm:py-10 px-4 shadow-md border-b border-[#F8EDEF]/20\">\n      <div class=\"max-w-5xl mx-auto text-center space-y-2\">\n        <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight text-white m-0\">\n          GIÁO TRÌNH QUẢN TRỊ CHIẾN LƯỢC\n        </h1>\n        <div class=\"pt-2 flex flex-wrap justify-center gap-3 text-xs text-white\">\n          <span class=\"bg-black/20 px-3 py-1 rounded\">Chủ biên: <strong>ThS. Nguyễn Thị Trúc Phương</strong></span>\n        </div>\n      </div>\n    </header>\n\n    <!-- THANH ĐIỀU HƯỚNG MỤC LỤC NHANH (STICKY NAV) -->\n    <nav class=\"no-print sticky top-0 z-40 bg-white/95 backdrop-blur-md border-b border-[#E5E7EB] shadow-sm py-2 px-4\">\n      <div class=\"max-w-5xl mx-auto flex items-center justify-between gap-4 overflow-x-auto text-xs sm:text-sm font-medium text-gray-700\">\n        <span class=\"font-bold text-[#A83245] whitespace-nowrap flex items-center gap-1\">\n          <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253\"></path></svg>\n          Mục lục:\n        </span>\n        <div class=\"flex items-center gap-2 sm:gap-4 whitespace-nowrap\">\n          <a href=\"#loi-gioi-thieu\" class=\"hover:text-[#A83245] hover:underline\">Lời mở đầu</a>\n          <a href=\"#chuan-dau-ra\" class=\"hover:text-[#A83245] hover:underline\">Chuẩn đầu ra</a>\n          <a href=\"#chuong-1\" class=\"hover:text-[#A83245] hover:underline\">Chương 1: Nhập môn QTCL</a>\n          <a href=\"#chuong-2\" class=\"hover:text-[#A83245] hover:underline\">Chương 2: Môi trường KD</a>\n          <a href=\"#chuong-3\" class=\"hover:text-[#A83245] hover:underline\">Chương 3: Sứ mệnh &amp; Mục tiêu</a>\n          <a href=\"#chuong-4\" class=\"hover:text-[#A83245] hover:underline\">Chương 4: Lựa chọn chiến lược</a>\n          <a href=\"#chuong-5\" class=\"hover:text-[#A83245] hover:underline\">Chương 5: Thực thi chiến lược</a>\n          <a href=\"#chuong-6\" class=\"hover:text-[#A83245] hover:underline\">Chương 6: Đánh giá &amp; BSC</a>\n          <a href=\"#tai-lieu-tham-khao\" class=\"hover:text-[#A83245] hover:underline\">Tài liệu tham khảo</a>\n        </div>\n      </div>\n    </nav>\n\n    <!-- NỘI DUNG CHÍNH (MAIN BODY CONTAINER) -->\n    <main class=\"max-w-5xl mx-auto px-4 py-8 space-y-12 leading-relaxed\">\n\n      <!-- PHẦN THÔNG TIN TỔNG QUAN HỌC PHẦN -->\n      <section id=\"loi-gioi-thieu\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b border-[#F8EDEF] pb-4\">\n          <span class=\"text-xs font-bold text-[#A83245] uppercase tracking-wider\">Thông tin học phần chính quy</span>\n          <h2 class=\"text-xl sm:text-2xl font-bold text-[#111827] mt-1\">LỜI GIỚI THIỆU &amp; MỤC TIÊU HỌC PHẦN</h2>\n        </div>\n        \n        <div class=\"space-y-4 text-sm sm:text-base text-gray-700\">\n          <p>\n            Giáo trình <strong>Quản trị chiến lược (Mã học phần: MH17)</strong> là học phần chuyên môn cốt lõi, mang tính chất tổng hợp và đỉnh cao trong chương trình đào tạo ngành <em>Quản trị kinh doanh</em> tại Trường Cao đẳng Kinh tế Thành phố Hồ Chí Minh. Môn học trang bị cho sinh viên thế giới quan và phương pháp luận khoa học để nhìn nhận tổ chức doanh nghiệp trong mối quan hệ hữu cơ với môi trường kinh doanh đầy biến động và cạnh tranh gay gắt.\n          </p>\n          <p>\n            Quản trị chiến lược không chỉ là tập hợp của các kỹ thuật hoạch định tĩnh mà là một <strong>tiến trình quản trị năng động, liên tục</strong> gồm ba giai đoạn không thể tách rời: <em>Hoạch định chiến lược (Strategy Formulation)</em>, <em>Thực thi chiến lược (Strategy Implementation)</em> và <em>Đánh giá - Kiểm soát chiến lược (Strategy Evaluation &amp; Control)</em>. Sinh viên sẽ được rèn luyện tư duy phân tích đa chiều thông qua các công cụ chuẩn mực quốc tế như mô hình PESTEL, 5 áp lực cạnh tranh của Michael Porter, chuỗi giá trị (Value Chain), ma trận IFE, EFE, CPM, SWOT, BCG, SPACE, QSPM và hệ thống Thẻ điểm cân bằng (Balanced Scorecard - BSC).\n          </p>\n        </div>\n\n        <!-- MỤC TIÊU HỌC PHẦN -->\n        <div id=\"chuan-dau-ra\" class=\"grid grid-cols-1 md:grid-cols-3 gap-4 pt-2\">\n          <div class=\"p-4 rounded-lg bg-[#F7F5F2] border-l-4 border-[#A83245] space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm flex items-center gap-2\">\n              <span class=\"w-6 h-6 rounded-full bg-[#A83245] text-white flex items-center justify-center text-xs\">1</span>\n              Chuẩn Kiến thức (Knowledge)\n            </h3>\n            <p class=\"text-xs text-gray-600\">\n              Nắm vững bản chất chiến lược, các cấp độ chiến lược (Công ty, SBU, Chức năng). Hiểu sâu sắc các yếu tố môi trường vĩ mô, vi mô, nội bộ và thành thạo nguyên lý xây dựng các ma trận chiến lược.\n            </p>\n          </div>\n          <div class=\"p-4 rounded-lg bg-[#F7F5F2] border-l-4 border-[#A83245] space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm flex items-center gap-2\">\n              <span class=\"w-6 h-6 rounded-full bg-[#A83245] text-white flex items-center justify-center text-xs\">2</span>\n              Chuẩn Kỹ năng (Skills)\n            </h3>\n            <p class=\"text-xs text-gray-600\">\n              Thu thập, xử lý dữ liệu thị trường thực tế; lập ma trận IFE, EFE, CPM, SWOT, BCG, SPACE; phân tích lựa chọn phương án chiến lược tối ưu và xây dựng kế hoạch hành động bằng Thẻ điểm cân bằng BSC.\n            </p>\n          </div>\n          <div class=\"p-4 rounded-lg bg-[#F7F5F2] border-l-4 border-[#A83245] space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm flex items-center gap-2\">\n              <span class=\"w-6 h-6 rounded-full bg-[#A83245] text-white flex items-center justify-center text-xs\">3</span>\n              Năng lực Tự chủ &amp; Trách nhiệm\n            </h3>\n            <p class=\"text-xs text-gray-600\">\n              Hình thành tư duy phản biện, khả năng làm việc nhóm, kỹ năng giải quyết vấn đề phức tạp và đạo đức nghề nghiệp trong việc ra các quyết định chiến lược có trách nhiệm với xã hội.\n            </p>\n          </div>\n        </div>\n\n        <!-- BẢNG TỔNG HỢP CHỮ VIẾT TẮT -->\n        <div class=\"pt-4 border-t border-gray-100\">\n          <h4 class=\"text-xs font-bold text-gray-800 uppercase tracking-wider mb-2\">Danh mục chữ viết tắt học thuật</h4>\n          <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs\">\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#A83245]\">SBU:</strong> Strategic Business Unit (Đơn vị kinh doanh chiến lược)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#A83245]\">PESTEL:</strong> Chính trị, Kinh tế, Xã hội, Công nghệ, Môi trường, Pháp lý</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#A83245]\">EFE:</strong> External Factor Evaluation (Ma trận yếu tố ngoại vi)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#A83245]\">IFE:</strong> Internal Factor Evaluation (Ma trận yếu tố nội vi)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#A83245]\">CPM:</strong> Competitive Profile Matrix (Ma trận hình ảnh cạnh tranh)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#A83245]\">SWOT:</strong> Strengths, Weaknesses, Opportunities, Threats</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#A83245]\">BCG:</strong> Boston Consulting Group Matrix (Ma trận BCG)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#A83245]\">BSC:</strong> Balanced Scorecard (Thẻ điểm cân bằng)</div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 1: NHẬP MÔN QUẢN TRỊ CHIẾN LƯỢC -->\n      <!-- ========================================== -->\n      <section id=\"chuong-1\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#A83245] pb-3\">\n          <span class=\"text-xs font-bold text-[#A83245] uppercase tracking-wider\">Chương 1</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">NHẬP MÔN QUẢN TRỊ CHIẾN LƯỢC</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">1.1. Khái niệm và Bản chất của Chiến lược Kinh doanh</h3>\n            <p>\n              Thuật ngữ <em>\"Chiến lược\" (Strategy)</em> có nguồn gốc từ tiếng Hy Lạp cổ là <em>\"Strategos\"</em>, với nghĩa ban đầu là nghệ thuật chỉ huy quân sự của các tướng lĩnh trên chiến trường. Khi du nhập vào lĩnh vực kinh tế và quản trị kinh doanh từ giữa thế kỷ XX, khái niệm này đã phát triển thành hệ thống tư tưởng định hướng tương lai cho doanh nghiệp:\n            </p>\n            <blockquote class=\"my-3 p-4 bg-[#F8EDEF]/30 border-l-4 border-[#A83245] rounded-r text-gray-800 italic\">\n              \"Chiến lược là việc xác định các mục tiêu dài hạn cơ bản của một doanh nghiệp, cùng với việc thông qua các chuỗi hành động và sự phân bổ các nguồn lực cần thiết để đạt được những mục tiêu đó.\"\n              <footer class=\"text-xs text-gray-500 font-semibold mt-1\">— Alfred Chandler (1962), Strategy and Structure</footer>\n            </blockquote>\n            <p>\n              Theo giáo sư <strong>Michael Porter</strong> (Đại học Harvard), bản chất cốt lõi của chiến lược là <em>sự khác biệt hóa</em>: \"Chiến lược cạnh tranh là việc chọn lựa có chủ đích một chuỗi các hoạt động khác biệt nhằm mang lại một giá trị độc nhất vô nhị cho khách hàng. Chiến lược không phải là làm tốt hơn những gì đối thủ đang làm (đó chỉ là hiệu quả vận hành), mà là làm những gì đối thủ không làm hoặc làm theo cách thức hoàn toàn khác biệt.\"\n            </p>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">1.2. Ba Cấp Độ Chiến Lược Trong Doanh Nghiệp</h3>\n            <p>\n              Trong một tổ chức kinh doanh hiện đại, đặc biệt là các tập đoàn đa ngành hoặc doanh nghiệp quy mô lớn, chiến lược được phân tầng thành 3 cấp độ liên kết chặt chẽ với nhau:\n            </p>\n            <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 my-4\">\n              <div class=\"p-4 bg-gray-50 rounded-lg border border-gray-200\">\n                <span class=\"text-xs font-bold text-[#A83245] uppercase\">Cấp độ 1</span>\n                <h4 class=\"font-bold text-gray-900 mt-1 mb-2\">Chiến lược Cấp Công ty (Corporate Strategy)</h4>\n                <p class=\"text-xs text-gray-600\">\n                  Xác định định hướng tổng thể của toàn bộ doanh nghiệp: Chúng ta nên tham gia vào những ngành kinh doanh nào? Phân bổ nguồn lực giữa các đơn vị kinh doanh như thế nào? Quyết định mua bán sáp nhập (M&amp;A), đa dạng hóa hay thu hẹp hoạt động.\n                </p>\n              </div>\n              <div class=\"p-4 bg-gray-50 rounded-lg border border-gray-200\">\n                <span class=\"text-xs font-bold text-[#A83245] uppercase\">Cấp độ 2</span>\n                <h4 class=\"font-bold text-gray-900 mt-1 mb-2\">Chiến lược Cấp Đơn vị Kinh doanh (Business/SBU Strategy)</h4>\n                <p class=\"text-xs text-gray-600\">\n                  Xác định cách thức một đơn vị kinh doanh chiến lược (SBU) cạnh tranh thành công trong một ngành hoặc phân khúc thị trường cụ thể: Dẫn đầu chi phí thấp, Khác biệt hóa sản phẩm, hay Tập trung vào thị trường ngách.\n                </p>\n              </div>\n              <div class=\"p-4 bg-gray-50 rounded-lg border border-gray-200\">\n                <span class=\"text-xs font-bold text-[#A83245] uppercase\">Cấp độ 3</span>\n                <h4 class=\"font-bold text-gray-900 mt-1 mb-2\">Chiến lược Cấp Chức năng (Functional Strategy)</h4>\n                <p class=\"text-xs text-gray-600\">\n                  Kế hoạch hành động cụ thể tại các bộ phận chức năng (Marketing, Tài chính, Nghiên cứu &amp; Phát triển - R&amp;D, Sản xuất/Vận hành, Nhân sự) nhằm hỗ trợ đắc lực và hiện thực hóa mục tiêu của chiến lược cấp SBU và công ty.\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">1.3. Tiến Trình Toàn Diện của Quản Trị Chiến Lược</h3>\n            <p>\n              Quản trị chiến lược là một chu trình khép kín gồm 3 giai đoạn cơ bản với mối quan hệ tương hỗ:\n            </p>\n            <div class=\"overflow-x-auto my-4 border rounded-lg\">\n              <table class=\"w-full text-left text-xs sm:text-sm\">\n                <thead class=\"bg-[#A83245] text-white\">\n                  <tr>\n                    <th class=\"p-3\">Giai đoạn</th>\n                    <th class=\"p-3\">Hoạt động trọng tâm</th>\n                    <th class=\"p-3\">Công cụ phân tích chủ đạo</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-gray-200 bg-white\">\n                  <tr>\n                    <td class=\"p-3 font-semibold text-gray-900\">1. Hoạch định chiến lược (Formulation)</td>\n                    <td class=\"p-3\">Nghiên cứu môi trường vĩ mô, vi mô; khảo sát nội bộ; xác định sứ mệnh, tầm nhìn; thiết lập mục tiêu dài hạn; xây dựng và lựa chọn chiến lược tối ưu.</td>\n                    <td class=\"p-3 font-mono text-[#A83245]\">PESTEL, Porter 5 Forces, IFE, EFE, CPM, SWOT, SPACE, BCG, QSPM</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-semibold text-gray-900\">2. Thực thi chiến lược (Implementation)</td>\n                    <td class=\"p-3\">Thiết lập mục tiêu ngắn hạn; ban hành chính sách; tái cấu trúc bộ máy tổ chức; phân bổ nguồn lực; xây dựng văn hóa doanh nghiệp hỗ trợ chiến lược.</td>\n                    <td class=\"p-3 font-mono text-[#A83245]\">Sơ đồ tổ chức SBU, Ngân sách tài chính, Kế hoạch Marketing 4P/7P, Quản trị thay đổi</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-semibold text-gray-900\">3. Đánh giá &amp; Kiểm soát (Evaluation)</td>\n                    <td class=\"p-3\">Kiểm tra lại các tiền đề chiến lược; đo lường thành quả thực tế; so sánh với mục tiêu đặt ra; đề xuất các giải pháp khắc phục sai lệch kịp thời.</td>\n                    <td class=\"p-3 font-mono text-[#A83245]\">Balanced Scorecard (BSC), Chỉ số KPI, Kiểm soát ngân sách, Kế hoạch dự phòng</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP VÀ BÀI TẬP CHƯƠNG 1 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#A83245] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Thảo luận Chương 1\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Trình bày định nghĩa chiến lược kinh doanh và phân tích sự khác biệt cốt lõi giữa \"Hiệu quả vận hành\" (Operational Effectiveness) và \"Định vị chiến lược\" (Strategic Positioning) theo Michael Porter.</li>\n              <li>Phân tích mối quan hệ hữu cơ giữa 3 cấp độ chiến lược trong một tập đoàn đa ngành. Lấy ví dụ minh họa từ Tập đoàn Vingroup hoặc Vinamilk.</li>\n              <li>Tại sao nói giai đoạn thực thi chiến lược (Implementation) thường là giai đoạn khó khăn nhất và dễ thất bại nhất trong tiến trình quản trị chiến lược?</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 2: NGHIÊN CỨU MÔI TRƯỜNG KINH DOANH -->\n      <!-- ========================================== -->\n      <section id=\"chuong-2\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#A83245] pb-3\">\n          <span class=\"text-xs font-bold text-[#A83245] uppercase tracking-wider\">Chương 2</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">NGHIÊN CỨU CÁC YẾU TỐ MÔI TRƯỜNG KINH DOANH</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">2.1. Phân Tích Môi Trường Vĩ Mô — Khung PESTEL</h3>\n            <p>\n              Môi trường vĩ mô bao gồm các yếu tố nằm ngoài doanh nghiệp và ngành, tác động bao trùm đến mọi chủ thể trong nền kinh tế. Doanh nghiệp không thể kiểm soát được môi trường vĩ mô mà phải chủ động dự báo để thích nghi:\n            </p>\n            <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4 my-4 text-xs sm:text-sm\">\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">P - Political (Chính trị):</strong> Sự ổn định chính trị, định hướng của Đảng và Nhà nước, chính sách ngoại giao, an ninh quốc gia.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">E - Economic (Kinh tế):</strong> Tốc độ tăng trưởng GDP, tỷ lệ lạm phát, lãi suất ngân hàng, tỷ giá hối đoái, thu nhập bình quân đầu người và sức mua.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">S - Social (Xã hội &amp; Văn hóa):</strong> Cơ cấu dân số vàng/già hóa, xu hướng tiêu dùng xanh, lối sống số, trình độ học vấn, phong tục tập quán.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">T - Technological (Công nghệ):</strong> Trí tuệ nhân tạo (AI), tự động hóa, chuyển đổi số, thương mại điện tử, tốc độ lỗi thời của công nghệ cũ.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">E - Environmental (Môi trường sinh thái):</strong> Biến đổi khí hậu, phát thải ròng (Net Zero), ô nhiễm, nguồn tài nguyên thiên nhiên khan hiếm.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">L - Legal (Pháp lý):</strong> Luật Doanh nghiệp, Luật Đầu tư, Luật Sở hữu trí tuệ, các hiệp định thương mại tự do (EVFTA, CPTPP).\n              </div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">2.2. Phân Tích Môi Trường Ngành — Mô Hình 5 Áp Lực Cạnh Tranh (Michael Porter)</h3>\n            <p>\n              Cường độ cạnh tranh và khả năng sinh lời trong một ngành kinh doanh được quyết định bởi 5 lực lượng cạnh tranh cốt lõi:\n            </p>\n            <div class=\"p-4 bg-gray-50 rounded-lg border border-gray-200 space-y-3 text-xs sm:text-sm\">\n              <div><strong class=\"text-[#A83245]\">1. Sự cạnh tranh giữa các đối thủ hiện tại trong ngành:</strong> Căng thẳng gia tăng khi số lượng đối thủ đông đảo, quy mô tương đương, tốc độ tăng trưởng ngành chậm lại, hoặc chi phí cố định cao dẫn đến chiến tranh giá.</div>\n              <div><strong class=\"text-[#A83245]\">2. Nguy cơ từ các đối thủ tiềm ẩn mới gia nhập:</strong> Phụ thuộc vào các <em>Rào cản gia nhập (Barriers to entry)</em> như tính kinh tế theo quy mô (Economies of Scale), bằng sáng chế, yêu cầu vốn đầu tư ban đầu, chi phí chuyển đổi nhà cung cấp của khách hàng.</div>\n              <div><strong class=\"text-[#A83245]\">3. Áp lực đe dọa từ sản phẩm/dịch vụ thay thế:</strong> Các sản phẩm khác ngành nhưng đáp ứng cùng nhu cầu cơ bản với tỷ số giá/hiệu năng hấp dẫn (ví dụ: đường sắt cao tốc thay thế hàng không cự ly ngắn).</div>\n              <div><strong class=\"text-[#A83245]\">4. Quyền lực thương lượng của Nhà cung cấp:</strong> Nhà cung cấp có ưu thế khi ngành cung ứng độc quyền nhóm, sản phẩm có tính độc đáo cao, hoặc chi phí chuyển đổi nhà cung cấp của doanh nghiệp rất lớn.</div>\n              <div><strong class=\"text-[#A83245]\">5. Quyền lực thương lượng của Khách hàng:</strong> Khách hàng có quyền lực mạnh khi họ mua khối lượng lớn, sản phẩm tiêu chuẩn hóa không khác biệt, hoặc họ có khả năng hội nhập ngược về phía sau.</div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">2.3. Ma Trận Đánh Giá Các Yếu Tố Ngoại Vi (EFE Matrix)</h3>\n            <p>\n              Ma trận EFE tóm tắt và đánh giá các cơ hội (Opportunities) và thách thức (Threats) từ môi trường bên ngoài. Quy trình thiết lập gồm 5 bước: liệt kê yếu tố, gán trọng số (tổng = 1.00), xếp hạng phản ứng (1 đến 4), tính điểm trọng số và tổng kết.\n            </p>\n            <div class=\"overflow-x-auto my-3 border rounded-lg\">\n              <table class=\"w-full text-left text-xs\">\n                <thead class=\"bg-[#A83245] text-white\">\n                  <tr>\n                    <th class=\"p-2\">Các yếu tố bên ngoài then chốt (Key External Factors)</th>\n                    <th class=\"p-2 text-center\">Trọng số (Weight)</th>\n                    <th class=\"p-2 text-center\">Xếp loại (Rating: 1-4)</th>\n                    <th class=\"p-2 text-center\">Điểm có trọng số (Weighted Score)</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-gray-200 bg-white\">\n                  <tr class=\"bg-green-50/50\"><td colspan=\"4\" class=\"p-2 font-bold text-green-800\">Cơ hội (Opportunities)</td></tr>\n                  <tr><td class=\"p-2\">1. Xu hướng tiêu dùng các sản phẩm hữu cơ, có nguồn gốc tự nhiên tăng 15%/năm</td><td class=\"p-2 text-center\">0.15</td><td class=\"p-2 text-center\">4</td><td class=\"p-2 text-center font-bold\">0.60</td></tr>\n                  <tr><td class=\"p-2\">2. Ký kết các FTA mở rộng cơ hội xuất khẩu sang thị trường Châu Âu &amp; Nhật Bản</td><td class=\"p-2 text-center\">0.10</td><td class=\"p-2 text-center\">3</td><td class=\"p-2 text-center font-bold\">0.30</td></tr>\n                  <tr><td class=\"p-2\">3. Sự bùng nổ của kênh phân phối trực tuyến (E-commerce &amp; Livestream)</td><td class=\"p-2 text-center\">0.15</td><td class=\"p-2 text-center\">3</td><td class=\"p-2 text-center font-bold\">0.45</td></tr>\n                  <tr class=\"bg-red-50/50\"><td colspan=\"4\" class=\"p-2 font-bold text-red-800\">Thách thức (Threats)</td></tr>\n                  <tr><td class=\"p-2\">4. Giá nguyên vật liệu đầu vào và chi phí logistics biến động mạnh</td><td class=\"p-2 text-center\">0.20</td><td class=\"p-2 text-center\">2</td><td class=\"p-2 text-center font-bold\">0.40</td></tr>\n                  <tr><td class=\"p-2\">5. Các đối thủ ngoại nhập quy mô toàn cầu đẩy mạnh thâm nhập thị trường</td><td class=\"p-2 text-center\">0.25</td><td class=\"p-2 text-center\">2</td><td class=\"p-2 text-center font-bold\">0.50</td></tr>\n                  <tr><td class=\"p-2\">6. Quy định nghiêm ngặt về tiêu chuẩn bảo vệ môi trường và giảm phát thải</td><td class=\"p-2 text-center\">0.15</td><td class=\"p-2 text-center\">3</td><td class=\"p-2 text-center font-bold\">0.45</td></tr>\n                  <tr class=\"bg-gray-100 font-bold\">\n                    <td class=\"p-2 uppercase\">Tổng cộng</td>\n                    <td class=\"p-2 text-center\">1.00</td>\n                    <td class=\"p-2 text-center\">-</td>\n                    <td class=\"p-2 text-center text-[#A83245] text-sm\">2.70</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n            <p class=\"text-xs text-gray-600 italic\">\n              <strong>Ý nghĩa phân tích:</strong> Tổng điểm trung bình của ma trận là 2.50. Tổng số điểm 2.70 cho thấy doanh nghiệp đang phản ứng ở mức trên trung bình đối với các cơ hội và thách thức từ môi trường bên ngoài.\n            </p>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">2.4. Phân Tích Nội Bộ — Chuỗi Giá Trị và Ma Trận IFE</h3>\n            <p>\n              Khung phân tích <em>Chuỗi giá trị (Value Chain)</em> của Michael Porter chia hoạt động của doanh nghiệp thành 2 nhóm:\n            </p>\n            <ul class=\"list-disc list-inside space-y-1 text-xs sm:text-sm pl-2\">\n              <li><strong>Hoạt động chính (Primary Activities):</strong> Hậu cần nhập (Inbound Logistics), Vận hành/Sản xuất (Operations), Hậu cần xuất (Outbound Logistics), Marketing &amp; Bán hàng, Dịch vụ sau bán hàng.</li>\n              <li><strong>Hoạt động hỗ trợ (Support Activities):</strong> Cơ sở hạ tầng công ty, Quản trị nguồn nhân lực, Phát triển công nghệ (R&amp;D), Hoạt động mua sắm (Procurement).</li>\n            </ul>\n            <p class=\"mt-2\">\n              Tương tự như EFE, <strong>Ma trận Đánh giá các Yếu tố Nội vi (IFE Matrix)</strong> được xây dựng nhằm định lượng các Điểm mạnh cốt lõi (Xếp loại 3 hoặc 4) và Điểm yếu (Xếp loại 1 hoặc 2) của tổ chức.\n            </p>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 2 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#A83245] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Bài tập thực hành Chương 2\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Phân tích 5 áp lực cạnh tranh của Michael Porter đối với ngành bán lẻ hiện đại (siêu thị, cửa hàng tiện lợi) tại Việt Nam hiện nay.</li>\n              <li>Nêu quy tắc gán trọng số và xếp loại trong Ma trận EFE và IFE. Tại sao điểm tổng có trọng số 2.5 được coi là mức ngưỡng trung bình?</li>\n              <li><strong>Bài tập nhóm:</strong> Chọn một doanh nghiệp cụ thể (ví dụ: VinFast hoặc Highland Coffee), lập danh mục 10 yếu tố nội vi và xây dựng Ma trận IFE hoàn chỉnh.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 3: XÁC ĐỊNH SỨ MỆNH VÀ MỤC TIÊU -->\n      <!-- ========================================== -->\n      <section id=\"chuong-3\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#A83245] pb-3\">\n          <span class=\"text-xs font-bold text-[#A83245] uppercase tracking-wider\">Chương 3</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">XÁC ĐỊNH SỨ MỆNH, TẦM NHÌN VÀ MỤC TIÊU CHIẾN LƯỢC</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">3.1. Bản Tuyên Bố Sứ Mệnh (Mission Statement)</h3>\n            <p>\n              Sứ mệnh là bản tuyên bố khẳng định lý do tồn tại của tổ chức, phân biệt doanh nghiệp này với các đối thủ cạnh tranh khác. Bản tuyên bố sứ mệnh chuẩn mực học thuật theo Fred R. David cần trả lời câu hỏi <em>\"Hoạt động kinh doanh của chúng ta là gì?\"</em> và bao hàm <strong>9 thành phần cốt lõi</strong>:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-2 my-3 text-xs\">\n              <div class=\"bg-gray-50 p-2 rounded border\"><strong>1. Khách hàng:</strong> Ai là người thụ hưởng sản phẩm?</div>\n              <div class=\"bg-gray-50 p-2 rounded border\"><strong>2. Sản phẩm/Dịch vụ:</strong> Mặt hàng cốt lõi là gì?</div>\n              <div class=\"bg-gray-50 p-2 rounded border\"><strong>3. Thị trường:</strong> Cạnh tranh ở khu vực địa lý nào?</div>\n              <div class=\"bg-gray-50 p-2 rounded border\"><strong>4. Công nghệ:</strong> Nền tảng công nghệ có hiện đại không?</div>\n              <div class=\"bg-gray-50 p-2 rounded border\"><strong>5. Sự sống còn, tăng trưởng:</strong> Cam kết về tài chính.</div>\n              <div class=\"bg-gray-50 p-2 rounded border\"><strong>6. Triết lý kinh doanh:</strong> Giá trị cốt lõi, niềm tin.</div>\n              <div class=\"bg-gray-50 p-2 rounded border\"><strong>7. Tự đánh giá năng lực:</strong> Năng lực vượt trội là gì?</div>\n              <div class=\"bg-gray-50 p-2 rounded border\"><strong>8. Hình ảnh cộng đồng:</strong> Trách nhiệm với xã hội.</div>\n              <div class=\"bg-gray-50 p-2 rounded border\"><strong>9. Quan tâm nhân viên:</strong> Nhân viên có là tài sản quý?</div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">3.2. Bản Tuyên Bố Tầm Nhìn (Vision Statement)</h3>\n            <p>\n              Nếu sứ mệnh hướng về hiện tại thì <em>Tầm nhìn (Vision)</em> hướng về tương lai 5 đến 10 năm tới: <strong>\"Doanh nghiệp chúng ta mong muốn trở thành cái gì?\"</strong>. Tầm nhìn cần ngắn gọn, truyền cảm hứng mạnh mẽ, định hướng và khơi dậy khát vọng cống hiến của toàn thể cán bộ nhân viên.\n            </p>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">3.3. Thiết Lập Hệ Thống Mục Tiêu Chiến Lược Theo Tiêu Chuẩn SMART</h3>\n            <p>\n              Mục tiêu chiến lược là những kết quả cụ thể mà doanh nghiệp nỗ lực đạt được trong dài hạn. Mọi mục tiêu khoa học phải thỏa mãn 5 nguyên tắc vàng SMART:\n            </p>\n            <div class=\"p-4 bg-gray-50 rounded-lg border border-gray-200 text-xs sm:text-sm space-y-2\">\n              <p><strong class=\"text-[#A83245]\">S - Specific (Cụ thể):</strong> Mục tiêu phải rõ ràng, không mơ hồ, tập trung vào kết quả cụ thể.</p>\n              <p><strong class=\"text-[#A83245]\">M - Measurable (Đo lường được):</strong> Có chỉ số định lượng cụ thể (doanh thu, lợi nhuận, % thị phần).</p>\n              <p><strong class=\"text-[#A83245]\">A - Achievable (Khả thi):</strong> Đầy thách thức nhưng nằm trong giới hạn năng lực và nguồn lực.</p>\n              <p><strong class=\"text-[#A83245]\">R - Relevant (Phù hợp):</strong> Phù hợp với sứ mệnh, tầm nhìn và bối cảnh ngành của doanh nghiệp.</p>\n              <p><strong class=\"text-[#A83245]\">T - Time-bound (Có thời hạn):</strong> Xác định rõ thời điểm hoàn thành (quý, năm, giai đoạn 5 năm).</p>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 3 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#A83245] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Thảo luận Chương 3\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Phân biệt sự khác nhau giữa Sứ mệnh (Mission) và Tầm nhìn (Vision) của doanh nghiệp.</li>\n              <li>Trình bày 9 thành phần trong bản tuyên bố sứ mệnh theo Fred R. David. Đánh giá bản tuyên bố sứ mệnh của một doanh nghiệp Việt Nam theo 9 thành phần này.</li>\n              <li>Viết lại một mục tiêu chung chung: \"Gia tăng lợi nhuận bán hàng\" thành mục tiêu đạt chuẩn SMART hoàn chỉnh.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 4: LỰA CHỌN VÀ XÂY DỰNG CHIẾN LƯỢC -->\n      <!-- ========================================== -->\n      <section id=\"chuong-4\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#A83245] pb-3\">\n          <span class=\"text-xs font-bold text-[#A83245] uppercase tracking-wider\">Chương 4</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">LỰA CHỌN VÀ XÂY DỰNG CHIẾN LƯỢC</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">4.1. Ma Trận SWOT — Phối Hợp Các Chiến Lược Cốt Lõi</h3>\n            <p>\n              Ma trận SWOT là công cụ kết hợp các yếu tố bên trong và bên ngoài để hình thành 4 nhóm chiến lược hành động:\n            </p>\n            <div class=\"overflow-x-auto my-3 border rounded-lg\">\n              <table class=\"w-full text-left text-xs\">\n                <thead class=\"bg-[#A83245] text-white\">\n                  <tr>\n                    <th class=\"p-3 w-1/3\">Ma trận SWOT</th>\n                    <th class=\"p-3 w-1/3\">Điểm mạnh (Strengths - S)</th>\n                    <th class=\"p-3 w-1/3\">Điểm yếu (Weaknesses - W)</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-gray-200 bg-white\">\n                  <tr>\n                    <td class=\"p-3 font-bold bg-green-50 text-green-800\">Cơ hội (Opportunities - O)</td>\n                    <td class=\"p-3 bg-white\">\n                      <strong class=\"text-green-700\">Chiến lược SO (Maxi - Maxi):</strong>\n                      <p class=\"text-gray-600 mt-1\">Sử dụng các thế mạnh nội bộ sẵn có để nắm bắt và tận dụng triệt để các cơ hội từ thị trường bên ngoài.</p>\n                    </td>\n                    <td class=\"p-3 bg-white\">\n                      <strong class=\"text-blue-700\">Chiến lược WO (Mini - Maxi):</strong>\n                      <p class=\"text-gray-600 mt-1\">Tận dụng các cơ hội từ bên ngoài để khắc phục, hạn chế hoặc loại bỏ những điểm yếu nội bộ.</p>\n                    </td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold bg-red-50 text-red-800\">Thách thức (Threats - T)</td>\n                    <td class=\"p-3 bg-white\">\n                      <strong class=\"text-yellow-700\">Chiến lược ST (Maxi - Mini):</strong>\n                      <p class=\"text-gray-600 mt-1\">Phát huy thế mạnh nội bộ của doanh nghiệp để né tránh, đối phó hoặc giảm thiểu tác hại của các đe dọa bên ngoài.</p>\n                    </td>\n                    <td class=\"p-3 bg-white\">\n                      <strong class=\"text-red-700\">Chiến lược WT (Mini - Mini):</strong>\n                      <p class=\"text-gray-600 mt-1\">Chiến lược phòng thủ nhằm hạn chế tối đa các điểm yếu nội bộ đồng thời tránh các mối đe dọa từ môi trường.</p>\n                    </td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">4.2. Ma Trận BCG (Boston Consulting Group)</h3>\n            <p>\n              Ma trận BCG phân loại danh mục các đơn vị kinh doanh chiến lược (SBU) dựa trên 2 tiêu chí: <strong>Tốc độ tăng trưởng ngành</strong> (trục tung) và <strong>Thị phần tương đối</strong> so với đối thủ đứng đầu (trục hoành):\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 my-3 text-xs sm:text-sm\">\n              <div class=\"p-4 bg-yellow-50 rounded-lg border border-yellow-200\">\n                <span class=\"font-bold text-yellow-800 uppercase text-xs\">Ô Dấu Hỏi (Question Marks)</span>\n                <p class=\"text-xs text-gray-600 mt-1\">Tăng trưởng cao nhưng thị phần thấp. Cần lượng vốn đầu tư lớn để mở rộng. Doanh nghiệp cần quyết định đầu tư mạnh để đưa lên Ngôi sao hoặc thoái vốn.</p>\n              </div>\n              <div class=\"p-4 bg-blue-50 rounded-lg border border-blue-200\">\n                <span class=\"font-bold text-blue-800 uppercase text-xs\">Ô Ngôi Sao (Stars)</span>\n                <p class=\"text-xs text-gray-600 mt-1\">Tăng trưởng cao và thị phần tương đối cao. Cơ hội sinh lợi tốt nhất trong dài hạn. Chiến lược tích hợp dọc, thâm nhập thị trường, bảo vệ vị thế dẫn đầu.</p>\n              </div>\n              <div class=\"p-4 bg-green-50 rounded-lg border border-green-200\">\n                <span class=\"font-bold text-green-800 uppercase text-xs\">Ô Bò Sữa (Cash Cows)</span>\n                <p class=\"text-xs text-gray-600 mt-1\">Tăng trưởng thấp nhưng thị phần cao. Tạo ra dòng tiền dồi dào mà không đòi hỏi tái đầu tư lớn. Doanh nghiệp dùng tiền mặt từ Bò sữa để nuôi dưỡng ô Dấu hỏi và Ngôi sao.</p>\n              </div>\n              <div class=\"p-4 bg-gray-100 rounded-lg border border-gray-300\">\n                <span class=\"font-bold text-gray-800 uppercase text-xs\">Ô Con Chó (Dogs)</span>\n                <p class=\"text-xs text-gray-600 mt-1\">Tăng trưởng thấp và thị phần thấp. Khả năng sinh lời yếu hoặc thua lỗ. Chiến lược: thu hẹp hoạt động, cắt giảm chi phí tối đa hoặc giải thể thanh lý tài sản.</p>\n              </div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">4.3. Ba Chiến Lược Cạnh Tranh Tổng Quát của Michael Porter</h3>\n            <div class=\"space-y-3 text-xs sm:text-sm\">\n              <div class=\"p-3 bg-gray-50 rounded border-l-4 border-[#A83245]\">\n                <strong class=\"text-gray-900\">1. Chiến lược Dẫn đầu chi phí thấp (Overall Cost Leadership):</strong> Hướng tới việc trở thành nhà sản xuất có chi phí thấp nhất trong toàn ngành thông qua tính kinh tế theo quy mô, tối ưu hóa công nghệ và quản lý chặt chẽ chi phí chung (ví dụ: Walmart, Vietjet Air).\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border-l-4 border-[#A83245]\">\n                <strong class=\"text-gray-900\">2. Chiến lược Khác biệt hóa sản phẩm (Differentiation):</strong> Tạo ra sản phẩm hoặc dịch vụ được khách hàng cảm nhận là độc nhất vô nhị trên toàn ngành thông qua thiết kế, thương hiệu, công nghệ vượt trội hoặc dịch vụ khách hàng xuất sắc (ví dụ: Apple, Mercedes-Benz).\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border-l-4 border-[#A83245]\">\n                <strong class=\"text-gray-900\">3. Chiến lược Tập trung hóa (Focus Strategy):</strong> Doanh nghiệp tập trung toàn lực vào một phân khúc thị trường hẹp (thị trường ngách), có thể là Tập trung vào chi phí thấp hoặc Tập trung vào khác biệt hóa (ví dụ: các dòng siêu xe thể thao, dịch vụ tư vấn tài chính chuyên biệt).\n              </div>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 4 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#A83245] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Thảo luận Chương 4\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Trình bày ý nghĩa của 4 nhóm chiến lược SO, WO, ST, WT trong ma trận SWOT. Cho ví dụ thực tế.</li>\n              <li>Phân tích mối quan hệ chuyển dịch giữa 4 ô trong Ma trận BCG. Một SBU ở ô \"Bò sữa\" có thể chuyển thành ô nào khi thị trường biến động?</li>\n              <li>Phân tích rủi ro của tình trạng \"Mắc kẹt ở giữa\" (Stuck in the middle) theo quan điểm của Michael Porter khi một doanh nghiệp không chọn rõ rệt chiến lược chi phí thấp hay khác biệt hóa.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 5: THỰC THI CHIẾN LƯỢC -->\n      <!-- ========================================== -->\n      <section id=\"chuong-5\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#A83245] pb-3\">\n          <span class=\"text-xs font-bold text-[#A83245] uppercase tracking-wider\">Chương 5</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">THỰC THI CHIẾN LƯỢC</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">5.1. Bản Chất và Thách Thức của Giai Đoạn Thực Thi</h3>\n            <p>\n              Nếu hoạch định chiến lược là việc <em>\"định vị quân cờ trước khi khai cuộc\"</em> thì thực thi chiến lược là việc <em>\"vận hành các quân cờ trong thực tế chiến đấu\"</em>. Nhà quản trị thường gặp thất bại ở khâu thực thi do thiếu gắn kết giữa chiến lược với cấu trúc tổ chức, chính sách khen thưởng và văn hóa doanh nghiệp:\n            </p>\n            <div class=\"overflow-x-auto my-3 border rounded-lg\">\n              <table class=\"w-full text-left text-xs\">\n                <thead class=\"bg-[#A83245] text-white\">\n                  <tr>\n                    <th class=\"p-3\">Tiêu chí so sánh</th>\n                    <th class=\"p-3\">Hoạch định chiến lược (Formulation)</th>\n                    <th class=\"p-3\">Thực thi chiến lược (Implementation)</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-gray-200 bg-white\">\n                  <tr>\n                    <td class=\"p-3 font-semibold text-gray-900\">Trọng tâm định vị</td>\n                    <td class=\"p-3\">Tập trung vào hiệu quả chiến lược (Doing the right things)</td>\n                    <td class=\"p-3\">Tập trung vào hiệu quả tác nghiệp (Doing things right)</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-semibold text-gray-900\">Bản chất quá trình</td>\n                    <td class=\"p-3\">Chủ yếu là quá trình trí tuệ và tư duy phân tích logic</td>\n                    <td class=\"p-3\">Chủ yếu là quá trình vận hành, quản trị con người và tâm lý</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-semibold text-gray-900\">Kỹ năng đòi hỏi</td>\n                    <td class=\"p-3\">Đòi hỏi kỹ năng trực giác và kỹ năng phân tích chuyên sâu</td>\n                    <td class=\"p-3\">Đòi hỏi kỹ năng lãnh đạo, tạo động lực và phối hợp nhân sự</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-semibold text-gray-900\">Số lượng người tham gia</td>\n                    <td class=\"p-3\">Một nhóm nhỏ các nhà quản trị cấp cao và chuyên gia tư vấn</td>\n                    <td class=\"p-3\">Toàn thể cán bộ công nhân viên và các cấp quản lý trong công ty</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">5.2. Tương Thích Giữa Cơ Cấu Tổ Chức và Chiến Lược</h3>\n            <p>\n              Nguyên lý kinh điển của Alfred Chandler khẳng định: <strong>\"Cơ cấu tổ chức phải đi theo chiến lược\" (Structure follows Strategy)</strong>. Khi doanh nghiệp thay đổi định hướng chiến lược (ví dụ từ chuyên môn hóa một sản phẩm sang đa dạng hóa nhiều ngành), cơ cấu tổ chức phải được điều chỉnh tương ứng:\n            </p>\n            <ul class=\"list-disc list-inside space-y-1 text-xs sm:text-sm pl-2\">\n              <li><strong>Cơ cấu chức năng:</strong> Phù hợp với chiến lược tập trung một ngành hàng, tối ưu hóa chuyên môn hóa sâu.</li>\n              <li><strong>Cơ cấu phân chia theo đơn vị SBU / Khu vực địa lý:</strong> Phù hợp với doanh nghiệp đa ngành, phân quyền tự chủ cao cho từng giám đốc SBU.</li>\n              <li><strong>Cơ cấu ma trận:</strong> Kết hợp giữa quản lý chức năng và quản lý theo dự án/sản phẩm, tăng tính linh hoạt nhưng đòi hỏi sự phối hợp cao để tránh xung đột mệnh lệnh kép.</li>\n            </ul>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">5.3. Triển Khai Chiến Lược Chức Năng</h3>\n            <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4 my-3 text-xs sm:text-sm\">\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">Chiến lược Marketing:</strong> Thực hiện phân đoạn thị trường (Segmentation), lựa chọn thị trường mục tiêu (Targeting), định vị thương hiệu (Positioning) và tối ưu phối thức Marketing-Mix (4P/7P).\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">Chiến lược Tài chính:</strong> Lập dự toán ngân sách, huy động vốn nợ và vốn chủ sở hữu, quản trị dòng tiền ngắn hạn và tỷ lệ chi trả cổ tức.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">Chiến lược Vận hành &amp; R&amp;D:</strong> Tối ưu hóa chuỗi cung ứng, áp dụng tự động hóa, giảm thời gian đưa sản phẩm mới ra thị trường.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#A83245]\">Chiến lược Nguồn nhân lực:</strong> Tuyển dụng đúng nhân tài chiến lược, đào tạo nâng cao kỹ năng số, gắn chính sách lương thưởng với KPI chiến lược.\n              </div>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 5 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#A83245] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Thảo luận Chương 5\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Giải thích câu nói \"Structure follows Strategy\" của Alfred Chandler. Cho ví dụ về sự thay đổi cơ cấu tổ chức khi doanh nghiệp mở rộng thị trường ra quốc tế.</li>\n              <li>Liệt kê 4 nguyên nhân hàng đầu khiến các chiến lược kinh doanh được hoạch định xuất sắc nhưng thất bại trong khâu thực thi.</li>\n              <li>Làm thế nào để nhà quản trị vượt qua sự kháng cự thay đổi (Resistance to change) từ phía nhân viên khi triển khai một chiến lược chuyển đổi số mới?</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 6: ĐÁNH GIÁ VÀ KIỂM SOÁT CHIẾN LƯỢC -->\n      <!-- ========================================== -->\n      <section id=\"chuong-6\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#A83245] pb-3\">\n          <span class=\"text-xs font-bold text-[#A83245] uppercase tracking-wider\">Chương 6</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">KIỂM SOÁT VÀ ĐÁNH GIÁ CHIẾN LƯỢC — THẺ ĐIỂM CÂN BẰNG (BSC)</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">6.1. Quy Trình Kiểm Soát Chiến Lược 4 Bước</h3>\n            <p>\n              Kiểm soát chiến lược là khâu cuối cùng nhưng mang tính chất thường trực nhằm đảm bảo doanh nghiệp luôn đi đúng quỹ đạo đã định:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-4 gap-2 my-3 text-xs\">\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"font-bold text-[#A83245]\">Bước 1</span>\n                <p class=\"font-semibold text-gray-800 mt-1\">Thiết lập các tiêu chuẩn kiểm tra</p>\n                <p class=\"text-[11px] text-gray-500 mt-1\">Định lượng các chỉ tiêu tài chính và phi tài chính theo mốc thời gian.</p>\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"font-bold text-[#A83245]\">Bước 2</span>\n                <p class=\"font-semibold text-gray-800 mt-1\">Đo lường thành quả thực tế</p>\n                <p class=\"text-[11px] text-gray-500 mt-1\">Thu thập dữ liệu hoạt động chính xác từ hệ thống báo cáo quản trị.</p>\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"font-bold text-[#A83245]\">Bước 3</span>\n                <p class=\"font-semibold text-gray-800 mt-1\">So sánh thành quả với tiêu chuẩn</p>\n                <p class=\"text-[11px] text-gray-500 mt-1\">Xác định các độ lệch (Variances) vượt quá ngưỡng dung sai cho phép.</p>\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"font-bold text-[#A83245]\">Bước 4</span>\n                <p class=\"font-semibold text-gray-800 mt-1\">Thực hiện các hành động điều chỉnh</p>\n                <p class=\"text-[11px] text-gray-500 mt-1\">Điều chỉnh mục tiêu, phân bổ lại nguồn vốn hoặc kích hoạt kế hoạch dự phòng.</p>\n              </div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">6.2. Hệ Thống Thẻ Điểm Cân Bằng (Balanced Scorecard - BSC)</h3>\n            <p>\n              Được phát triển bởi Robert Kaplan và David Norton (Đại học Harvard), <strong>Thẻ điểm cân bằng (BSC)</strong> là công cụ đột phá khắc phục hạn chế của việc chỉ nhìn vào các chỉ số tài chính quá khứ. BSC đánh giá doanh nghiệp trên <strong>4 khía cạnh cân bằng</strong>:\n            </p>\n            <div class=\"overflow-x-auto my-3 border rounded-lg\">\n              <table class=\"w-full text-left text-xs\">\n                <thead class=\"bg-[#A83245] text-white\">\n                  <tr>\n                    <th class=\"p-3 w-1/4\">Khía cạnh (Perspective)</th>\n                    <th class=\"p-3 w-1/4\">Câu hỏi trọng tâm</th>\n                    <th class=\"p-3 w-1/4\">Chỉ số đo lường cốt lõi (KPIs)</th>\n                    <th class=\"p-3 w-1/4\">Mục tiêu chiến lược ví dụ</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-gray-200 bg-white\">\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">1. Tài chính (Financial)</td>\n                    <td class=\"p-3 text-gray-600\">\"Để thành công về mặt tài chính, chúng ta phải xuất hiện như thế nào trước các cổ đông?\"</td>\n                    <td class=\"p-3 font-mono text-[#A83245]\">ROE, ROA, EBITDA, Dòng tiền tự do (FCF), Biên lợi nhuận ròng</td>\n                    <td class=\"p-3\">Tăng trưởng doanh thu 18%/năm, duy trì ROE &gt; 22%.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">2. Khách hàng (Customer)</td>\n                    <td class=\"p-3 text-gray-600\">\"Để đạt được tầm nhìn, chúng ta phải xuất hiện như thế nào trước các khách hàng?\"</td>\n                    <td class=\"p-3 font-mono text-[#A83245]\">Thị phần (Market share), Điểm NPS, Tỷ lệ giữ chân khách hàng (CRR), Điểm hài lòng CSI</td>\n                    <td class=\"p-3\">Giữ chân 90% khách hàng trung thành, NPS đạt trên 70 điểm.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">3. Quy trình nội bộ (Internal Processes)</td>\n                    <td class=\"p-3 text-gray-600\">\"Để làm hài lòng khách hàng và cổ đông, chúng ta phải xuất sắc ở những quy trình nào?\"</td>\n                    <td class=\"p-3 font-mono text-[#A83245]\">Thời gian giao hàng (Lead time), Tỷ lệ lỗi sản phẩm (Defect rate), Tỷ lệ hoàn thành đơn hàng đúng hẹn (OTIF)</td>\n                    <td class=\"p-3\">Rút ngắn chu kỳ sản xuất 25%, kiểm soát lỗi &lt; 0.5%.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">4. Học hỏi &amp; Phát triển (Learning &amp; Growth)</td>\n                    <td class=\"p-3 text-gray-600\">\"Để hiện thực hóa tầm nhìn, tổ chức phải duy trì và phát triển năng lực đổi mới như thế nào?\"</td>\n                    <td class=\"p-3 font-mono text-[#A83245]\">Giờ đào tạo bình quân/nhân viên, Chỉ số gắn kết nhân viên, Tỷ lệ số hóa quy trình</td>\n                    <td class=\"p-3\">100% nhân viên hoàn thành khóa đào tạo kỹ năng số mới.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#A83245] mb-2\">6.3. Tình Huống Nghiên Cứu Thực Tế (Case Study)</h3>\n            <div class=\"p-4 bg-gray-50 rounded-lg border border-gray-200 text-xs sm:text-sm space-y-2\">\n              <span class=\"font-bold text-[#A83245] uppercase text-xs\">Nghiên cứu tình huống: Chiến lược vươn ra toàn cầu của Tập đoàn Viettel</span>\n              <p>\n                Tập đoàn Công nghiệp - Viễn thông Quân đội (Viettel) áp dụng triệt để chiến lược <strong>\"Lấy nông thôn vây thành thị\"</strong> khi thâm nhập các thị trường nước ngoài (Lào, Campuchia, Mozambique, Haiti, Burundi, Peru). Thay vì tập trung ngay vào các thành phố lớn đông đúc, Viettel đầu tư ồ ạt hạ tầng mạng lưới trạm BTS đến tận các vùng sâu vùng xa chưa có sóng viễn thông. Kết hợp với chính sách giá cước bình dân và kênh phân phối thẻ cào len lỏi tới từng làng bản, Viettel nhanh chóng chiếm lĩnh thị phần số 1 tại hầu hết các quốc gia đầu tư.\n              </p>\n              <p class=\"font-semibold text-gray-800\">Câu hỏi thảo luận tình huống:</p>\n              <ul class=\"list-disc list-inside pl-2 space-y-1 text-gray-600\">\n                <li>Phân tích loại hình chiến lược mà Viettel đã áp dụng theo khung lý thuyết chiến lược cạnh tranh của Michael Porter.</li>\n                <li>Những rủi ro chính trị và rủi ro tỷ giá mà Viettel phải đối mặt khi mở rộng sang các thị trường châu Phi và Mỹ Latinh là gì? Viettel đã kiểm soát các rủi ro này như thế nào?</li>\n              </ul>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 6 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#A83245] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Đánh giá tổng hợp Chương 6\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Trình bày 4 khía cạnh của Thẻ điểm cân bằng (Balanced Scorecard - BSC). Tại sao BSC được xem là công cụ đo lường toàn diện và bền vững hơn hệ thống báo cáo tài chính truyền thống?</li>\n              <li>Nêu các nguyên nhân khiến một kế hoạch kiểm soát chiến lược bị thất bại trong thực tế quản trị.</li>\n              <li>Phân tích tầm quan trọng của việc xây dựng \"Kế hoạch dự phòng\" (Contingency Planning) trong bối cảnh môi trường kinh doanh bất định toàn cầu hiện nay.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- TÀI LIỆU THAM KHẢO CHÍNH THỨC -->\n      <!-- ========================================== -->\n      <section id=\"tai-lieu-tham-khao\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-4\">\n        <h3 class=\"text-base font-bold text-[#A83245] uppercase tracking-wider border-b border-gray-100 pb-2\">\n          Tài Liệu Tham Khảo Học Thuật Chuẩn\n        </h3>\n        <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n          <li><strong>ThS. Nguyễn Thị Trúc Phương</strong> (Chủ biên), <em>Giáo trình Quản trị chiến lược (MH17)</em>, Khoa Quản trị kinh doanh, Trường Cao đẳng Kinh tế Thành phố Hồ Chí Minh.</li>\n          <li><strong>Fred R. David &amp; Forest R. David</strong> (2020), <em>Strategic Management: A Competitive Advantage Approach, Concepts and Cases</em> (17th Edition), Pearson Education.</li>\n          <li><strong>Michael E. Porter</strong> (1998), <em>Competitive Strategy: Techniques for Analyzing Industries and Competitors</em>, Free Press.</li>\n          <li><strong>Robert S. Kaplan &amp; David P. Norton</strong> (1996), <em>The Balanced Scorecard: Translating Strategy into Action</em>, Harvard Business Review Press.</li>\n          <li><strong>Henry Mintzberg, Bruce Ahlstrand &amp; Joseph Lampel</strong> (2009), <em>Strategy Safari: A Guided Tour Through The Wilds of Strategic Management</em>, Free Press.</li>\n        </ol>\n      </section>\n\n    </main>\n\n    <!-- FOOTER TRANG HỌC LIỆU SỐ -->\n    \n    <!-- THÔNG TIN BẢN QUYỀN HỌC THUẬT CHUẨN MỰC TƯƠNG PHẢN CAO -->\n    <div class=\"no-print w-full bg-white border border-[#E5E7EB] rounded-xl py-6 px-4 text-center text-xs space-y-1.5 shadow-xs my-6\">\n      <p class=\"text-[#A83245] font-extrabold text-sm m-0\">BẢN QUYỀN HỌC LIỆU SỐ THUỘC VỀ KHOA QUẢN TRỊ KINH DOANH — GIẢNG VIÊN ThS. NGUYỄN THỊ TRÚC PHƯƠNG</p>\n      <p class=\"text-gray-600 m-0\">Hệ thống số hóa giáo trình phục vụ công tác đào tạo chính quy trình độ Cao đẳng &amp; Đại học.</p>\n    </div>\n  \n\n  </div>\n  ";
